  function applySlotIcon(el3, slot) {
    if (slot === "ear") {
      el3.innerHTML = earIconHtml();
      return;
    }
    if (slot === "wing") {
      el3.innerHTML = wingIconHtml();
      return;
    }
    if (slot === "tail") {
      el3.innerHTML = tailIconHtml();
      return;
    }
    el3.textContent = slotIconLabel(slot);
  }
