    if (debounceTimer != null) {
      clearTimeout(debounceTimer);
      debounceTimer = null;
    }
    if (onWindowFocus) {
      window.removeEventListener("focus", onWindowFocus);
      onWindowFocus = null;
    }
    if (onFocusIn) {
      document.removeEventListener("focusin", onFocusIn);
      onFocusIn = null;
    }
